package com.danil.blackswordsman;
import java.io.*;
public final class ExportV6Models {public static void main(String[] args)throws Exception{File dir=new File("build/model-qa");dir.mkdirs();for(int id=0;id<4;id++){GameWorld.Actor a=new GameWorld.Actor();a.type=id==3?GameWorld.FLESH_HOUND:-1;a.height=id==3?1.1f:2.1f;a.radius=id==3?.66f:.52f;a.speed=5;a.yaw=.15f;if(id==1){a.attackTime=.45f;a.attackKind=5;a.attackBlend=1;}if(id==2){a.animationSpeed=1;a.gaitPhase=1.4f;}SkinGeometry data=new SkinGeometry(a,true);CharacterSkeleton.Pose p=new CharacterSkeleton.Pose();CharacterSkeleton.sample(a,0,p);float[] palette=new float[256];data.palette(p,a.yaw,palette);float[] v=data.vertices.clone();for(int i=0;i<v.length;i+=16){float x=v[i],y=v[i+1],z=v[i+2],nx=v[i+3],ny=v[i+4],nz=v[i+5];for(int row=0;row<3;row++){float pos=0,n=0;for(int part=0;part<2;part++){int o=(int)v[i+11+part]*16;float weight=v[i+13+part];pos+=(palette[o+row]*x+palette[o+4+row]*y+palette[o+8+row]*z+palette[o+12+row])*weight;n+=(palette[o+row]*nx+palette[o+4+row]*ny+palette[o+8+row]*nz)*weight;}v[i+row]=pos;v[i+3+row]=n;}}DataOutputStream out=new DataOutputStream(new FileOutputStream(new File(dir,id+".bin")));out.writeInt(v.length);out.writeInt(data.indices.length);for(float f:v)out.writeFloat(f);for(short q:data.indices)out.writeShort(q);out.close();}}}
